import React from 'react';
import styled from '@emotion/styled';
import { motion } from 'framer-motion';

const HeroSection = styled.section`
  min-height: 60vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background: linear-gradient(135deg, ${props => props.theme.colors.primary} 0%, #6c5ce7 100%);
  position: relative;
  overflow: hidden;
`;

const ExploreButton = styled(motion.button)`
  padding: 1rem 2rem;
  font-size: 1.2rem;
  background: white;
  color: ${props => props.theme.colors.primary};
  border: none;
  border-radius: 30px;
  cursor: pointer;
  transition: transform 0.3s ease;
  
  &:hover {
    transform: scale(1.05);
  }
`;

const Hero: React.FC = () => {
  return (
    <HeroSection>
      <ExploreButton
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.95 }}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8, delay: 0.4 }}
      >
        Explore Workouts
      </ExploreButton>
    </HeroSection>
  );
};

export default Hero;
